import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Submit contact form, then use browser back and retry', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Which service are you interested in', 'Functional Testing')
  await opFill(page, 'Name', 'John Doe')
  await opFill(page, 'Email', 'john@example.com')
  await opPress(page, 'Enter')
  await opClick(page, 'button', 'Back')
  await opPress(page, 'Tab')
  await opPress(page, 'Enter')
  await opSeen(page, 'heading', 'Thank you! We\'ll be in touch shortly')
})
